const prisma = require('../utils/prismaClient')
const { ValidationError, NotFoundError } = require('../utils/errors')
const { createRefund } = require('./paystackService')

// References generated by POST /api/payments/paystack/initialize. Charges
// with other references were made outside DASHPOS and are ignored.
const POS_REFERENCE_PREFIX = 'POS-'

/**
 * Record a successful charge from the charge.success webhook, linked to its
 * sale if the POS already created one. Safe to call more than once.
 * @returns {object|null} the record, or null if the charge isn't from DASHPOS
 */
async function recordCharge(data) {
  const reference = data?.reference
  if (!reference || !reference.startsWith(POS_REFERENCE_PREFIX)) return null

  const payment = await prisma.payment.findUnique({ where: { reference } })
  const saleId = payment?.sale_id ?? null

  return prisma.paystackPayment.upsert({
    where: { reference },
    create: {
      reference,
      amount: Number(data.amount),
      currency: data.currency || 'GHS',
      channel: data.channel || null,
      customer_email: data.customer?.email || null,
      paid_at: data.paid_at ? new Date(data.paid_at) : null,
      sale_id: saleId,
    },
    update: saleId ? { sale_id: saleId } : {},
  })
}

/**
 * Successful charges with no sale and no completed refund, newest first.
 * Links any record whose sale was created at the same moment as the webhook
 * arrived, so it isn't shown as unmatched.
 */
async function listUnmatched() {
  const candidates = await prisma.paystackPayment.findMany({
    where: { sale_id: null, refunded_at: null },
    orderBy: { created_at: 'desc' },
  })
  if (candidates.length === 0) return []

  const payments = await prisma.payment.findMany({
    where: { reference: { in: candidates.map((c) => c.reference) } },
    select: { reference: true, sale_id: true },
  })
  const saleByReference = new Map(payments.map((p) => [p.reference, p.sale_id]))

  const unmatched = []
  for (const record of candidates) {
    const saleId = saleByReference.get(record.reference)
    if (saleId) {
      await prisma.paystackPayment.update({ where: { id: record.id }, data: { sale_id: saleId } })
    } else {
      unmatched.push(record)
    }
  }
  return unmatched
}

/**
 * Refund an unmatched payment through Paystack. Completes when the
 * refund.processed webhook arrives (see markRefunded).
 */
async function refundUnmatched(id) {
  const record = await prisma.paystackPayment.findUnique({ where: { id } })
  if (!record) throw new NotFoundError('Payment not found')

  const sale = await prisma.payment.findUnique({ where: { reference: record.reference } })
  if (record.sale_id || sale) {
    throw new ValidationError('Payment has a sale', [
      { field: 'id', message: 'This payment belongs to a sale. Refund it from the Sales page instead.' },
    ])
  }

  // Claim the refund first so two requests can't both reach Paystack
  const { count } = await prisma.paystackPayment.updateMany({
    where: { id, sale_id: null, refunded_at: null, refund_requested_at: null },
    data: { refund_requested_at: new Date() },
  })
  if (count === 0) {
    throw new ValidationError('Refund already requested', [
      { field: 'id', message: 'A refund for this payment is already requested or done' },
    ])
  }

  try {
    await createRefund(record.reference)
  } catch (err) {
    await prisma.paystackPayment.update({ where: { id }, data: { refund_requested_at: null } })
    throw err
  }

  return prisma.paystackPayment.findUnique({ where: { id } })
}

/** refund.processed for an unmatched payment. @returns {boolean} whether one was updated */
async function markRefunded(reference) {
  const { count } = await prisma.paystackPayment.updateMany({
    where: { reference, sale_id: null, refunded_at: null },
    data: { refunded_at: new Date() },
  })
  return count > 0
}

/** refund.failed for an unmatched payment: allow the refund to be retried. */
async function clearRefundRequest(reference) {
  const { count } = await prisma.paystackPayment.updateMany({
    where: { reference, sale_id: null, refunded_at: null },
    data: { refund_requested_at: null },
  })
  return count > 0
}

module.exports = {
  POS_REFERENCE_PREFIX,
  recordCharge,
  listUnmatched,
  refundUnmatched,
  markRefunded,
  clearRefundRequest,
}
